import{_ as i,C as r,o as s,c as l,a2 as t,j as o,a,E as d}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"KomaYomi（格读）— local-first manga intensive reading","titleTemplate":false,"description":"KomaYomi（格读） documentation — local-first, panel-by-panel manga intensive reading. Compare Japanese, Chinese and English editions side by side, pin notes to the artwork, and export study pages; your files never leave your machine.","frontmatter":{"layout":"home","titleTemplate":false,"description":"KomaYomi（格读） documentation — local-first, panel-by-panel manga intensive reading. Compare Japanese, Chinese and English editions side by side, pin notes to the artwork, and export study pages; your files never leave your machine.","title":"KomaYomi（格读）— local-first manga intensive reading","hero":{"name":"KomaYomi（格读）","text":"Read manga panel by panel","tagline":"Japanese, Chinese and English on one page — notes and marks pinned to the drawing. Local-first, no account.","image":{"src":"/assets/screenshots/hero-real-library.webp","alt":"Compare reader with three language panes from a real library; the manga artwork is blurred"},"actions":[{"theme":"brand","text":"Get started","link":"/guide/introduction"},{"theme":"alt","text":"Data formats","link":"/data-format"}]},"features":[{"title":"Panels first","details":"Automatic XY-cut detection with manual drawing, merging, numbering and reusable layout templates. Notes and marks follow the artwork when panels are re-detected or a template is applied, so a re-layout no longer loses work."},{"title":"Compare multiple languages","details":"Side-by-side or overlay views, per-language masks, wheel zoom and pan, plus page / panel / anchor / grid alignment with reusable presets."},{"title":"Notes that travel","details":"Markdown notes at page or panel scope in typed cards, optional pins on the artwork, tags, sources, a scratch pad, full-text search and one-click \\"copy context\\" for pasting into an LLM."},{"title":"Portable output","details":"Export HTML with an image folder or as a single embedded file, render page / panel / collage PNGs, share images for social posts, and move everything as a `.mnproj` project."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1794842245000}'),p={name:"index.md"};function m(h,e,c,g,u,y){const n=r("Badge");return s(),l("div",null,[e[4]||(e[4]=t('<h2 id="why-komayomi-exists" tabindex="-1">Why KomaYomi exists <a class="header-anchor" href="#why-komayomi-exists" aria-label="Permalink to &quot;Why KomaYomi exists&quot;">​</a></h2><p>Studying a manga in a second language usually means three windows — the original, a translation, and a dictionary — plus a notes app that never lines up with the page. KomaYomi（格读） puts the same page in Japanese, Chinese and English in one window, cuts it into panels, and lets you pin Markdown notes and marks to the exact drawing. The unit of work is the panel, not the page.</p><p>It is a local web application: page images stay in a <code>raw/</code> folder, and every panel, note, tag and annotation lives in plain JSON under <code>data/</code>. Nothing leaves the machine unless you export it. Bring your own scans; it is a study tool, not a manga host.</p><p>Author homepages: <a href="https://x.com/payayakamo" target="_blank" rel="noopener noreferrer">X · @payayakamo</a> · <a href="https://note.com/payayakamo" target="_blank" rel="noopener noreferrer">note · @payayakamo</a>. These are the author&#39;s personal pages, not a product site.</p><h2 id="try-it-in-three-steps" tabindex="-1">Try it in three steps <a class="header-anchor" href="#try-it-in-three-steps" aria-label="Permalink to &quot;Try it in three steps&quot;">​</a></h2><ol><li><strong>Install or run.</strong> Download a build from <a href="https://github.com/PayayaKamo/KomaYomi/releases" target="_blank" rel="noopener noreferrer">GitHub Releases</a>, or run <code>npm install &amp;&amp; npm run dev</code> and open <code>http://127.0.0.1:5173</code>.</li><li><strong>Point it at pages.</strong> Put images under <code>raw/&lt;volume&gt;/&lt;language&gt;/&lt;chapter&gt;/001.jpg</code>, or use <strong>File → Open library folder…</strong>.</li><li><strong>Open a chapter.</strong> Panels are detected on first open as a draft; read in the compare view, write notes, export.</li></ol><p>Full install options, first-run folder layout and panel correction are in <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a> and <a href="/KomaYomi-docs/guide/introduction">Introduction</a>.</p><h2 id="status-at-a-glance" tabindex="-1">Status at a glance <a class="header-anchor" href="#status-at-a-glance" aria-label="Permalink to &quot;Status at a glance&quot;">​</a></h2><p>KomaYomi（格读） is at <strong>1.1.0</strong>. This site separates what works today from what is planned.</p><div class="status-list"><div><strong>Reading</strong> — library scanning including multi-work roots; three sidebar page-list layouts; panel detection and manual editing; splitting and renumbering; layout templates; compare reader with per-language masks; an original-page view; the enlarged 1:1 image viewer; previous/next panel across page and chapter boundaries with auto-centring; focus mode and read-only mode.</div><div><strong>Notes and marks</strong> — Markdown notes at page or panel scope; typed notes (Background, Vocabulary, Reaction, one type per enabled language, plus custom types and colours); pins on the artwork with grouped popovers; notes search; a single editor; vector annotations with anchor leaders, isolated per language, with a right-click menu; operation history wired to the undo stack.</div><div><strong>Projects and output</strong> — `.mnproj` projects that save back into the opened file; **Save as…** copies in the desktop app (download fallback in the browser); HTML, PNG, PDF (print) and Word export with annotations baked by default; Xiaohongshu-ready share images; backup ZIP and scheduled backups; cache management; WebDAV sources with an offline write queue; atomic page saves with schema validation, `.bak` rotation and a concurrent-write lock; CLI batch tools.</div><div><strong>Planned</strong> — vocabulary-list export; an in-app image format converter (renaming and splitting live in preprocessing); broader integration tests.</div></div>',10)),o("p",null,[e[0]||(e[0]=a("Anything marked ",-1)),d(n,{type:"warning",text:"Planned"}),e[1]||(e[1]=a(" in this site is ",-1)),e[2]||(e[2]=o("strong",null,"not implemented yet",-1)),e[3]||(e[3]=a(". If a page describes behavior that is not in the code, treat this note as authoritative and the feature as unavailable.",-1))]),e[5]||(e[5]=t('<h2 id="the-komayomi-repositories" tabindex="-1">The KomaYomi repositories <a class="header-anchor" href="#the-komayomi-repositories" aria-label="Permalink to &quot;The KomaYomi repositories&quot;">​</a></h2><p>This site documents the desktop edition. The same project ships in three other forms:</p><ul><li><a href="https://github.com/PayayaKamo/KomaYomi" target="_blank" rel="noopener noreferrer">KomaYomi</a> — the full desktop edition (Electron plus a local server) that this documentation covers.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-online" target="_blank" rel="noopener noreferrer">KomaYomi-online</a> — a browser-only build that opens <code>.mnproj</code> projects, reads, annotates and exports without a server.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-mobile" target="_blank" rel="noopener noreferrer">KomaYomi-mobile</a> — a React Native app for Android and iOS; HarmonyOS NEXT is a placeholder for now.</li><li><a href="https://github.com/PayayaKamo/KomaYomi-docs" target="_blank" rel="noopener noreferrer">KomaYomi-docs</a> — the generated build of this site, pushed by CI; edit the docs in the main repository instead.</li></ul><p>Projects use the same page JSON and the same <code>.mnproj</code> format across the editions, so work can move between them.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>New here? Read <a href="/KomaYomi-docs/guide/introduction">Introduction</a>, then <a href="/KomaYomi-docs/guide/installation">Install &amp; Run</a>.</li><li>Want the mental model? Start with <a href="/KomaYomi-docs/concepts">Core Concepts</a>.</li><li>Building on the JSON or writing a plugin? Go to <a href="/KomaYomi-docs/data-format">Data Formats</a> and <a href="/KomaYomi-docs/extending">Layout Templates &amp; Plugins</a>.</li><li>Stuck on a missing page or a broken export? See <a href="/KomaYomi-docs/faq">FAQ &amp; Troubleshooting</a>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Documentation languages</p><p>English is the primary language. A Chinese translation lives under <code>/zh/</code> and a Japanese one under <code>/ja/</code>. Each page states its status separately.</p></div>',7))])}const w=i(p,[["render",m]]);export{b as __pageData,w as default};
